{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Acarbose, a polar carbohydrate-based drug, has an absolute oral bioavailability of <2% in humans, directly supporting low F for the similarly glycosidic and highly polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Pentosan polysulfate sodium, a sulfated polysaccharide, showed 0.5-1% oral bioavailability versus i.v. in healthy subjects, strongly relevant to the query's sulfate ester and sugar backbone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Glycyrrhizin, a glucuronic acid-containing glycoside, has an absolute oral bioavailability of approximately 0.25% in humans, supporting low F for the query's glucuronic acid moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Furosemide acyl glucuronide, the closest-scoring analogue, had a human extent of bioavailability of 0.15 (15%), below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Scutellarin, a glucuronide conjugate, had an estimated oral bioavailability of only 10.67% in humans, below the 20% threshold and consistent with low F for polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thiocolchicoside oral solution had a bioavailability of 0.27 relative to intramuscular dosing, above 20%, but this non-sulfated, more lipophilic glycoside is structurally distant from the polyanionic query and carries low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, sulfated N-acetylglucosamine-glucuronic acid disaccharide. Multiple human studies on structurally related carbohydrate, sulfated, and glucuronide-containing molecules report oral bioavailability well below 20% (acarbose <2%, pentosan polysulfate 0.5-1%, glycyrrhizin ~0.25%, furosemide acyl glucuronide 15%, scutellarin 10.67%). The only above-threshold analogue is a distant lipophilic glycoside, so low oral bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule; all evidence is from close analogues.",
    "Some records report systemic availability or relative bioavailability rather than strict absolute F versus IV.",
    "Human pharmacokinetic data for this specific sulfated disaccharide are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

